    question: '防火戸・防火ダンパーに関する記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '防火ダンパーは、防火区画を貫通するダクトに設置され、火災時に煙感知器・温度ヒューズ等の作動により自動的に閉鎖しダクトを介した延焼を防止する。', explanation: '適当。ダクトは防火区画を貫通しやすいため、火災時に自動閉鎖する防火ダンパーにより延焼経路を遮断する。' },
      { key: 'B', text: '防火ダンパーは、ダクトを介した延焼防止とは無関係であり、専ら換気風量の調整のみを目的とした機器である。', explanation: '不適当。防火ダンパーは火災時にダクトを介して煙・火炎が他区画へ伝播することを防止するために自動閉鎖する防火用の機器であり、風量調整（VD等）を目的とする一般のダンパーとは目的が異なる。' },
      { key: 'C', text: '常時開放式の防火戸は、その閉鎖の障害とならないよう、周辺に物品を放置しない等の維持管理上の配慮が必要である。', explanation: '適当。防火戸の閉鎖経路に物が置かれていると、火災時に確実に閉鎖できないおそれがあるため、維持管理上の注意が必要である。' },
      { key: 'D', text: '防火ダンパーの温度ヒューズは、一定温度に達すると溶融し、ダンパーを自動的に閉鎖させる感熱部品である。', explanation: '適当。温度ヒューズは所定温度で溶断し、ばね等の力でダンパー羽根を閉鎖させる機構に用いられる感熱部品である。' },
    ],
