    choices: [
      { key: 'A', text: 'BCP対策は、建物の設備計画とは無関係な経営上の概念であり、自家発電設備や水源確保等の設備計画とは関連性がないとされている。', explanation: '不適当。BCP（事業継続計画）は、災害時にも重要業務・機能を継続できるようにする計画であり、自家発電設備・蓄電池設備・水源確保等の設備計画は、BCP対策を実現するための具体的な手段として密接に関連しており、「設備計画とは無関係」というのは誤りである。' },
      { key: 'B', text: 'BCP対策としての水の確保には、受水槽の容量計画や、井戸水の活用等、複数の水源確保策が検討されることがある。', explanation: '適当。断水時にも一定期間の水の確保ができるよう、受水槽容量や代替水源の検討が行われることがある。' },
      { key: 'C', text: '免震構造・制振構造の採用は、地震時の設備機器への損傷リスクを低減し、BCP対策の一環として位置づけられることがある。', explanation: '適当。建物の耐震性能向上は設備機器の損傷防止にも寄与するため、BCP対策の観点からも評価される。' },
      { key: 'D', text: 'BCP対策における非常用発電設備の燃料備蓄量は、想定する災害時の必要運転継続時間を踏まえて計画されることが望ましいとされる。', explanation: '適当。長時間の停電を想定する場合、必要な運転継続時間に応じた燃料備蓄量の確保が計画上重要となる。' },
    ],
